      "narrative_beats": [
        {
          "beat_type": "Establishment",
          "description": "Sol is introduced at work repairing a broken porcelain bird with a missing wing, establishing the conservation room and its objects as central to the story.",
          "approximate_location": "opening",
          "confidence": 0.95
        },
        {
          "beat_type": "Object Introduction",
          "description": "Iva brings a reel labelled MARA / TAKE 4 with a red thread tied around its hub, introducing the recording and the absent figure of Mara as narrative elements.",
          "approximate_location": "early",
          "confidence": 0.95
        },
        {
          "beat_type": "Character Revelation",
          "description": "Iva clarifies that Mara is her aunt, not her mother, and that her mother never liked microphones — establishing family relationships and a subtle distinction between the two women.",
          "approximate_location": "middle",
          "confidence": 0.9
        },
        {
          "beat_type": "Separation of Objects",
          "description": "Sol separates the broken wing from the bird's body, giving the wing to Iva to carry upstairs while he keeps the body — physically splitting the object and the two characters.",
          "approximate_location": "late",
          "confidence": 0.88
        },
        {
          "beat_type": "Departure",
          "description": "Iva leaves with the tin and reel in her satchel; Sol remains at the bench, reinforcing the spatial and narrative division between the two characters.",
          "approximate_location": "closing",
          "confidence": 0.9
        }
      ],
      "tone_mood": "quiet and methodical",
      "tone_shifts": [
        "A faint undercurrent of personal history enters when Mara is identified as Iva's aunt, briefly warming the otherwise clinical atmosphere"
      ],
      "location": null,
      "time_of_day": null,
