    },
    {
      "scene_id": "scene_002",
      "narrative_beats": [
        {
          "beat_type": "Atmosphere Establishment",
          "description": "Dust drifts through an unlit projector beam housing, establishing the theatre as a dormant, memory-laden space before any action occurs.",
          "approximate_location": "opening",
          "confidence": 0.92
        },
        {
          "beat_type": "Inciting Revelation",
          "description": "The tape plays Mara's recorded voice delivering a cryptic line — 'If the bird sings twice, wait for the door' — introducing an enigmatic instruction that will recur.",
          "approximate_location": "early",
          "confidence": 0.97
        },
        {
          "beat_type": "Mysterious Encounter",
          "description": "An Elderly Visitor appears wearing a silver bird brooch and comments on Mara's delivery, implying personal knowledge of Mara without explaining it.",
          "approximate_location": "middle",
          "confidence": 0.95
        },
        {
          "beat_type": "Evasion",
          "description": "When asked if she knew Mara, the visitor looks toward the stage rather than answering, withholding information and deepening the mystery.",
          "approximate_location": "middle-late",
          "confidence": 0.93
        },
        {
          "beat_type": "Disruption and Withdrawal",
          "description": "A door slams offscreen; Iva collects her objects and leaves while the visitor remains in the aisle, leaving the encounter unresolved.",
          "approximate_location": "closing",
          "confidence": 0.88
        }
      ],
      "tone_mood": "eerie and suspended",
      "tone_shifts": [
        "The scene opens in quiet routine but shifts to unease when the tape plays the cryptic line",
        "The visitor's evasive response and the offscreen door slam deepen the tone from curious to unsettling"
      ],
      "location": null,
      "time_of_day": null,
      "int_ext": "INT",
      "characters_present": null
    },
    {
      "scene_id": "scene_003",
      "narrative_beats": [
        {
          "beat_type": "Reunion and Repair",
          "description": "Iva returns the wing to Sol, who aligns and tapes the fracture — reuniting the separated object, though the crack remains visible.",
          "approximate_location": "opening",
          "confidence": 0.93
        },
        {
          "beat_type": "Disclosure",
          "description": "Iva tells Sol that someone upstairs knew how Mara spoke, reporting the encounter with the visitor and raising the question of the visitor's identity.",
          "approximate_location": "early-middle",
          "confidence": 0.95
        },
        {
          "beat_type": "Inconclusive Speculation",
          "description": "Sol offers two possible explanations — a friend, or someone who heard the recording — but cannot identify the visitor, leaving the mystery open.",
          "approximate_location": "middle",
          "confidence": 0.9
        },
        {
          "beat_type": "Object Placement",
          "description": "Iva places the red-thread reel on a shelf and the empty tin stays on the bench, distributing the scene's key objects in ways that suggest their ongoing significance.",
          "approximate_location": "middle",
          "confidence": 0.82
        },
        {
          "beat_type": "New Complication",
          "description": "A child appears at the doorway to report that 'the lady with the bird' says the theatre is locked, reintroducing the visitor and prompting action.",
          "approximate_location": "late",
          "confidence": 0.95
        },
        {
          "beat_type": "Mobilisation",
          "description": "Iva takes the theatre key and Sol carries the repaired bird in both hands, setting both characters in motion toward the theatre.",
          "approximate_location": "closing",
          "confidence": 0.9
        }
      ],
      "tone_mood": "contemplative with growing unease",
      "tone_shifts": [
        "The scene begins in calm restoration but shifts toward unease as the visitor's identity is discussed",
        "The child's arrival introduces a new urgency that breaks the reflective mood"
      ],
      "location": null,
      "time_of_day": "LATE AFTERNOON",
      "int_ext": "INT",
      "characters_present": null
    },
    {
      "scene_id": "scene_004",
      "narrative_beats": [
        {
          "beat_type": "Return and Absence",
          "description": "Iva and Sol enter the theatre but find no visitor inside — only her dark scarf with the silver bird brooch left on the front-row seat, suggesting unexplained departure or disappearance.",
          "approximate_location": "opening",
          "confidence": 0.95
        },
        {
          "beat_type": "Object as Threshold",
          "description": "Iva does not touch the scarf; Sol places the repaired porcelain bird on the stage with care — both characters treat the objects as charged or significant without explanation.",
          "approximate_location": "early-middle",
          "confidence": 0.88
        },
        {
          "beat_type": "Reflective Statement",
          "description": "Iva notes that Mara would be eighty now, implying the visitor could not have been Mara herself — or raising the question of whether she could.",
          "approximate_location": "middle",
          "confidence": 0.9
        },
        {
          "beat_type": "Deflection",
          "description": "Sol responds that Iva's remark is not an answer, indicating both characters are circling an unspoken question neither will name directly.",
          "approximate_location": "middle",
          "confidence": 0.87
        },
        {
          "beat_type": "Supernatural or Inexplicable Intrusion",
          "description": "A voice from behind the curtain repeats Mara's recorded line exactly — with no tape deck running and no visible speaker — creating an unexplained recurrence of the recording's words.",
          "approximate_location": "late",
          "confidence": 0.97
        },
        {
          "beat_type": "Suspended Confrontation",
          "description": "Sol reaches for Iva's sleeve; both remain facing the curtain without moving or speaking. The scene closes in stillness, unresolved, with the repaired bird silent on the stage.",
          "approximate_location": "closing",
          "confidence": 0.95
        }
      ],
      "tone_mood": "uncanny and unresolved",
